formula:
{================ 四周新高（近52周高 + 温和突破 + 连续5日）================}
N52:=250; N4W:=20;
HH52:=HHV(H,N52);                         {近52周最高价}
NEAR52:=C>=HH52*0.95;                     {收盘在近一年高位(距高≤5%)}
BRKREF:=HHV(REF(C,1),N4W);                {前20日(4周)最高收盘}
BRK:=C>BRKREF;                           {今日创4周新高}
GENTLE:=C/BRKREF<=1.035;                 {突破幅度≤3.5%(温和，不透支)}
MA25V:=MA(C,25);
IND25:=C/MA25V>0.92 AND C/MA25V<1.12;    {不远离25日线(±区间)}
TREND:=MA(C,25)>MA(C,60);                {中期多头}
AMT5:=MA(VOL,5)*C*100/1e8;               {近5日均额(亿)}
LIQ:=AMT5>=1;                            {流动性过滤}
HOLD:=COUNT(C>=BRKREF,5)=5;              {连续5日收盘守住突破位(未回落)}
XG:=NEAR52 AND BRK AND GENTLE AND IND25 AND TREND AND LIQ AND HOLD;
{说明：本公式为日线形态，与 gen_fourweek_newhigh.py 口径一致；北交所流动性多数不达标自然剔除。}
